/**
 * TypeScript from the CMS's schema (GET /api/v1/schema), injected as
 * .astro/integrations/librepublish/cms.d.ts: each block type's data, each
 * collection's frontmatter, each global's data, SEO — and `CmsBlockMap`, so
 * `<Blocks>` and `block.type` narrow to the real data.
 *
 *   import type { Blocks, Collections, Globals } from "librepublish:types";
 */
import type { CmsSchema, JsonSchema } from "./types.js";

export function generateTypes(schema: CmsSchema): string {
  const lines: string[] = [
    "// Generated by @librepublish/astro from the CMS's schema. Don't edit: it's rewritten on every build.",
    'declare module "librepublish:types" {',
    '  import type { CmsBlock, CmsEntry, CmsGlobal, CmsPage } from "@librepublish/astro/client";',
    "  /** An asset's id (resolve it from `included.assets` or the cmsAssets() collection). */",
    "  export type AssetId = string;",
    "  /** A link: to a URL, a page by path, or an entry. */",
    '  export type Link = { kind: "url" | "page" | "entry"; value: string; collection?: string };',
    "  /** A reference to another record, as the CMS stores it. */",
    "  export type RecordRef = string;",
  ];

  const blockNames: string[] = [];
  for (const [slug, block] of Object.entries(schema.block_types)) {
    const name = `${pascal(slug)}Block`;
    blockNames.push(`    ${JSON.stringify(slug)}: ${name};`);
    lines.push(`  /** ${block.title} */`, `  export type ${name} = ${render(block.data, 1)};`);
  }
  lines.push("  export interface CmsBlockMap {", ...blockNames, "  }");
  lines.push("  /** Any block, its data narrowed by its type. */");
  lines.push("  export type Block = { [K in keyof CmsBlockMap]: CmsBlock<CmsBlockMap[K]> & { type: K } }[keyof CmsBlockMap];");

  const collections: string[] = [];
  for (const [slug, collection] of Object.entries(schema.collections)) {
    const name = `${pascal(slug)}Fields`;
    collections.push(`    ${JSON.stringify(slug)}: CmsEntry<${name}>;`);
    lines.push(`  /** ${collection.title} */`, `  export type ${name} = ${render(collection.frontmatter, 1)};`);
  }
  lines.push("  export interface Collections {", ...collections, "  }");

  const globals: string[] = [];
  for (const [slug, global] of Object.entries(schema.globals)) {
    const name = `${pascal(slug)}Global`;
    globals.push(`    ${JSON.stringify(slug)}: CmsGlobal<${name}>;`);
    lines.push(`  /** ${global.title} */`, `  export type ${name} = ${render(global.data, 1)};`);
  }
  lines.push("  export interface Globals {", ...globals, "  }");

  const pages: string[] = [];
  for (const [path, page] of Object.entries(schema.pages)) {
    pages.push(`    ${JSON.stringify(path)}: CmsPage<${render(page.frontmatter, 2)}>;`);
  }
  lines.push("  /** Pages that carry fields of their own, by path. */", "  export interface PagesWithFields {", ...pages, "  }");
  lines.push(`  export type Seo = ${render(schema.seo, 1)};`, "}", "");
  lines.push(
    "declare namespace App {",
    "  interface Locals {",
    "    /** A CMS client for this request, on pages rendered on demand (its answers' cache tags become Cache-Tag). */",
    '    cms: import("@librepublish/astro/client").CmsClient;',
    "    /** The cache tags this response will carry. */",
    "    cmsTags: Set<string>;",
    "  }",
    "}",
    "",
  );
  return lines.join("\n");
}

function render(schema: JsonSchema | undefined, depth: number): string {
  if (!schema) return "unknown";
  const pad = "  ".repeat(depth + 1);
  const cmsType = schema["x-cms-type"];
  if (cmsType === "asset") return "AssetId";
  if (cmsType === "link") return "Link";
  if (cmsType === "blocks") return "Block[]";
  if (cmsType === "record_ref") return "RecordRef";
  if (cmsType === "record_refs") return "RecordRef[]";
  if (schema.enum) return schema.enum.map((value) => JSON.stringify(value)).join(" | ") || "never";

  switch (schema.type) {
    case "string": return "string";
    case "integer":
    case "number": return "number";
    case "boolean": return "boolean";
    case "array": return `Array<${render(schema.items, depth)}>`;
    case "object": {
      const properties = Object.entries(schema.properties ?? {});
      if (properties.length === 0) return "Record<string, unknown>";
      const required = new Set(schema.required ?? []);
      const body = properties.map(([key, property]) => {
        const doc = property.title || property.description
          ? `${pad}/** ${[property.title, property.description].filter(Boolean).join(" — ").replace(/\*\//g, "*\\/")} */\n` : "";
        // The CMS sends an unset field as null as often as it leaves it out.
        const optional = !required.has(key);
        return `${doc}${pad}${JSON.stringify(key)}${optional ? "?" : ""}: ${render(property, depth + 1)}${optional ? " | null" : ""};`;
      });
      return `{\n${body.join("\n")}\n${"  ".repeat(depth)}}`;
    }
    default: return "unknown";
  }
}

function pascal(slug: string): string {
  return slug.split(/[^a-zA-Z0-9]+/).filter(Boolean).map((part) => part[0].toUpperCase() + part.slice(1)).join("") || "Unnamed";
}
